#!/usr/bin/env bash
# Regenerates the vendored data in this directory from the flake's nixpkgs.
# Run after bumping nixpkgs; commit the result.
#
# Vendored rather than read during evaluation: unpacking a source tarball to
# parse it would mean import-from-derivation on every eval of a nixnet config.
set -euo pipefail

vendor="$(dirname "$(readlink -f "$0")")"
repo="$(git -C "$vendor" rev-parse --show-toplevel)"

# ethtool from the flake's own nixpkgs, so the vendored data matches what nixnet builds against
nixpkgs="(builtins.getFlake \"$repo\").inputs.nixpkgs.legacyPackages.\${builtins.currentSystem}"
ethtoolSrc="$(nix build --impure --no-link --print-out-paths --expr "$nixpkgs.ethtool.src")"
ethtoolVersion="$(nix eval --impure --raw --expr "$nixpkgs.ethtool.version")"

ast="$(mktemp)"
out="$vendor/ethtool_descriptions.toml"
tmp="$(mktemp)"
trap 'rm -f "$ast" "$tmp"' EXIT

# pandoc expands the man page's own `.A2`/`.BI` macros and keeps the text
# verbatim, so the option list can be queried as a document rather than scraped
tar -xf "$ethtoolSrc" --wildcards -O '*/ethtool.8.in' | pandoc -f man -t json > "$ast"

mkTable() {
  jq -r --arg term "$1" -f "$vendor/man_options.jq" "$ast"
}

{
  echo "# Generated by vendor/update.sh from ethtool's man page."
  echo "# Do not edit; rerun the script after bumping nixpkgs."
  echo "ethtoolVersion = \"$ethtoolVersion\""
  echo
  echo "[offload]"
  mkTable "-K --features --offload"
  echo
  echo "[pause]"
  mkTable "-A --pause"
  echo
  echo "[ring]"
  mkTable "-G --set-ring"
} > "$tmp"
mv "$tmp" "$out"

echo "wrote $out ($ethtoolVersion)"
